buf_T *api_buf_ensure_loaded(Buffer buf, Error *err)
{
  buf_T *b = find_buffer_by_handle(buf, err);
  if (!b) {
    return NULL;
  }

  if (b->b_ml.ml_mfp == NULL && !buf_ensure_loaded(b)) {
    api_set_error(err, kErrorTypeException, "Failed to load buffer");
    return NULL;
  }

  return b;
